func Enrich(ctx context.Context, records []Record) ([]Enriched, error) {
	g, ctx := errgroup.WithContext(ctx)
	// Sized against what the upstream can serve, not against len(records).
	// Unbounded fan-out looks like the dependency failing, not like us.
	g.SetLimit(8)

	out := make([]Enriched, len(records))

	for i, rec := range records {
		g.Go(func() error {
			// Per-item deadline, so one slow upstream call cannot hold the
			// whole batch open until the parent deadline fires.
			ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
			defer cancel()

			detail, err := lookup(ctx, rec.ID)
			if err != nil {
				// %w keeps the chain so the caller can use errors.Is rather
				// than matching on the message text.
				return fmt.Errorf("lookup %s: %w", rec.ID, err)
			}

			// Index assignment, not append: no mutex needed because no two
			// goroutines touch the same slot.
			out[i] = Enriched{Record: rec, Detail: detail}
			return nil
		})
	}

	// Waits for every goroutine. The first error cancels ctx, so the rest
	// stop rather than running on for a result that is already discarded.
	if err := g.Wait(); err != nil {
		return nil, err
	}
	return out, nil
}
